p.tenant_id = #{tenantId}

  AND p.punch_time >= CAST(CONCAT(#{query.dateFrom}, ' 00:00:00') AS TIMESTAMP)


  AND p.punch_time <= CAST(CONCAT(#{query.dateTo}, ' 23:59:59') AS TIMESTAMP)


  AND (
    e.employee_no LIKE CONCAT('%', #{query.employeeKeyword}, '%')
    OR e.employee_name LIKE CONCAT('%', #{query.employeeKeyword}, '%')
    OR p.external_employee_id LIKE CONCAT('%', #{query.employeeKeyword}, '%')
  )


  AND p.source_system = #{query.sourceSystem}


  AND p.process_status = #{query.processStatus}


  AND p.punch_type = #{query.punchType}

mapper.select:
SELECT 
FROM punch_raw_log p
LEFT JOIN employee e ON e.id = p.employee_id AND e.tenant_id = p.tenant_id
WHERE p.tenant_id = #{tenantId}
  AND p.id = #{id}

SELECT 
FROM punch_raw_log p
LEFT JOIN employee e ON e.id = p.employee_id AND e.tenant_id = p.tenant_id
WHERE p.tenant_id = #{tenantId}
  AND p.source_system = #{sourceSystem}
  AND p.source_event_id = #{sourceEventId}

