  punch_type, device_id, device_name, raw_payload, import_batch_id, process_status, error_message, ignored_reason
) VALUES (
  #{tenantId}, #{employeeId}, #{externalEmployeeId}, #{sourceSystem}, #{sourceEventId}, #{punchTime},
  #{punchType}, #{deviceId}, #{deviceName}, #{rawPayload}, #{importBatchId}, #{processStatus}, #{errorMessage}, #{ignoredReason}
)

mapper.update:
UPDATE punch_raw_log
SET process_status = #{processStatus},
    ignored_reason = #{ignoredReason},
    updated_at = CURRENT_TIMESTAMP
WHERE tenant_id = #{tenantId}
  AND id = #{id}

UPDATE punch_raw_log
SET process_status = #{processStatus},
    error_message = #{errorMessage},
    updated_at = CURRENT_TIMESTAMP
WHERE tenant_id = #{tenantId}
  AND id = #{id}

